        ? `${d.borderWidth}px solid ${hex(d.borderColor, DESIGN_DEFAULTS.borderColor)}`
        : "1px solid transparent",
      boxShadow: shadowCss(
        d.shadowOn,
        d.shadowX,
        d.shadowY,
        d.shadowBlur,
        d.shadowSpread,
        d.shadowColor,
        DESIGN_DEFAULTS.shadowColor,
