  return (
    <div
      className={`min-w-0 rounded-lg p-4 ${skin.shell}`}
      // "-shell": the dashboard card for the Carousel showcase is
      // data-hook="widget-carousel" (widget-<id>), so the box needs its own.
      data-hook="widget-carousel-shell"
