  const sendCount = recipientsOf(draft);
  const standing = isStanding(draft.channel);

const [grain, setGrain] = useState(config.channel === "link" ? "month" : "day");
// Chart or table on Reviews over time, like Review Tracker (Ali, 17 Sep).
