        header: ({ column }) => <DataTableColumnHeader column={column} title="Mode" dataHook="templates-col-mode" />,
        sortingFn: byText,
        cell: ({ row }) => (
          <span className="text-muted-foreground">{CHANNELS[row.original.config.channel]?.label ?? ""}</span>
