        header: ({ column }) => <DataTableColumnHeader column={column} title="Source" dataHook="templates-col-source" />,
        sortingFn: byText,
        cell: ({ row }) => <SourceBadge source={row.original.source} hook={`template-${row.original.id}-source`} />,
