              <DataTablePagination
                table={table}
                dataHook="templates-pagination"
                className="w-auto"
                ariaLabel="Template pagination"
                // Same wording as Review Manager and the campaigns table.
                renderRowCount={({ startRow, endRow, totalRows }) =>
                  `${startRow} to ${endRow} of ${totalRows}`
